    width = observation.get("width", 0)
    data = observation.get("grid", [])
    me = observation.get("you", {})
    pos = me.get("position", (0, 0))
    x, y = pos if isinstance(pos, (list, tuple)) and len(pos) == 2 else (0, 0)

    # Helper to safely access grid around position
    def cell_at(px, py):
        if 0 <= py < height and 0 <= px < width:
