        return None

    # Look for simple local goals: stay near center, avoid walls (-1)
    # Prefer staying within bounds and moving toward the center when possible
    cx, cy = max(0, min(width - 1, width // 2)), max(0, min(height - 1, height // 2))
    dx = 0
    dy = 0

    # Compute direction toward center
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1

    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1

    # If blocked by edge or unknown, try to adjust
    def is_blocked(nx, ny):
