        # Then vertically
        if dy != 0 and not is_blocked(x, y + dy):
            return [0, dy]
        # Try staying or small detour
        for ax in (-1, 0, 1):
            for ay in (-1, 0, 1):
                if ax == 0 and ay == 0:
                    continue
                nx, ny = x + ax, y + ay
                if not is_blocked(nx, ny) and 0 <= nx < width and 0 <= ny < height:
                    return [ax, ay]

    # Default move toward center if available
    if dx != 0 or dy != 0:
